const input = $input.first().json;
const body = input.body || {};

// Required fields
const domain = body.domain;
if (!domain) {
  return [{
    json: {
      valid: false,
      error: { code: 400, message: 'domain requis', status: 'BAD_REQUEST' }
    }
  }];
}

// Optional fields with defaults
const categories = body.categories || ['simple', 'ambigu', 'multi-étape', 'elliptique'];
const countPerCategory = body.count_per_category || 10;
const toolsFocus = body.tools_focus || [];
const language = body.language || 'fr';

// API keys - from body or env
const generatorModel = body.generator?.model || $env.MODEL_ANTHROPIC || 'claude-haiku-4-5-20251001';
const generatorKey = body.generator?.api_key || $env.ANTHROPIC_API_KEY;
const reviewerModel = body.reviewer?.model || $env.MODEL_OPENAI || 'gpt-4o-mini';
const reviewerKey = body.reviewer?.api_key || $env.OPENAI_API_KEY;

// Qdrant config
const qdrantHost = $env.QDRANT_SHARED_1_HOST || 'host3.local';
const qdrantPort = $env.QDRANT_SHARED_1_PORT || '20001';
const qdrantApiKey = $env.QDRANT_SHARED_1_API_KEY || '';
const qdrantCollection = 'tools_index';

const errors = [];
if (!generatorKey) errors.push('Generator API key manquant');
if (!reviewerKey) errors.push('Reviewer API key manquant');

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: { code: 400, message: errors.join(', '), status: 'BAD_REQUEST' }
    }
  }];
}

// Generate job ID
const now = new Date();
const timestamp = now.toISOString().replace(/[-:]/g, '').replace('T', '_').substring(0, 15);
const jobId = `dataset_${domain.replace(/\s+/g, '_')}_${timestamp}`;

return [{
  json: {
    valid: true,
    config: {
      jobId,
      domain,
      categories,
      countPerCategory,
      toolsFocus,
      language,
      generatorModel,
      generatorKey,
      reviewerModel,
      reviewerKey,
      qdrantUrl: `http://${qdrantHost}:${qdrantPort}`,
      qdrantApiKey,
      qdrantCollection
    },
    stats: {
      startedAt: now.toISOString()
    }
  }
}];

const qdrantResponse = $input.first().json;
const config = $('Validate Input').first().json.config;

if (qdrantResponse.error || !qdrantResponse.result?.points) {
  return [{
    json: {
      error: true,
      message: 'Erreur récupération Qdrant: ' + (qdrantResponse.error?.message || 'Unknown')
    }
  }];
}

const points = qdrantResponse.result.points;
const toolsFocus = config.toolsFocus || [];

// Build tools reference for LLM prompt
let toolsReference = '';
const toolsList = [];

for (const p of points) {
  const pl = p.payload || {};
  const name = pl.name || pl.webhook_path || 'unknown';
  const webhookPath = pl.webhook_path || '';
  const description = pl.description || '';
  const keywords = (pl.keywords || []).slice(0, 8).join(', ');
  const operations = (pl.operations || []).map(op => `${op.id}(${op.type})`).join(', ');
  const useCases = (pl.use_cases || []).slice(0, 3).join('; ');

  toolsList.push(webhookPath || name);

  // Highlight focused tools
  const isFocused = toolsFocus.some(t => name.toLowerCase().includes(t.toLowerCase()) || webhookPath.toLowerCase().includes(t.toLowerCase()));
  const marker = isFocused ? ' [PRIORITAIRE]' : '';

  toolsReference += `\n### ${name}${marker}\n`;
  toolsReference += `- **webhook**: ${webhookPath}\n`;
  toolsReference += `- **description**: ${description}\n`;
  toolsReference += `- **keywords**: ${keywords}\n`;
  toolsReference += `- **operations**: ${operations}\n`;
  toolsReference += `- **use_cases**: ${useCases}\n`;
}

console.log(`[Dataset Generator] Loaded ${points.length} tools from Qdrant`);

// Prepare category items for loop
const categoryItems = config.categories.map(cat => ({
  json: {
    category: cat,
    config,
    toolsReference,
    toolsList
  }
}));

return categoryItems;

const input = $input.first().json;
const prevData = $('Prepare Claude Body').first().json;

if (input.error) {
  return [{
    json: {
      ...prevData,
      generatedCases: [],
      generatorError: input.error.message || 'Generator error',
      status: 'generator_failed'
    }
  }];
}

try {
  const content = input.content?.[0]?.text || '';

  // Extract JSON array from response
  const jsonMatch = content.match(/\[\s*\{[\s\S]*\}\s*\]/m);
  if (!jsonMatch) {
    return [{
      json: {
        ...prevData,
        generatedCases: [],
        generatorError: 'No JSON array found in response',
        status: 'generator_failed'
      }
    }];
  }

  const cases = JSON.parse(jsonMatch[0]);
  console.log(`[Dataset Generator] Generated ${cases.length} cases for category: ${prevData.category}`);

  return [{
    json: {
      ...prevData,
      generatedCases: cases,
      generatorUsage: input.usage || {},
      status: 'generated'
    }
  }];
} catch (e) {
  return [{
    json: {
      ...prevData,
      generatedCases: [],
      generatorError: 'Parse error: ' + e.message,
      status: 'generator_failed'
    }
  }];
}

