const input = $input.first().json;
const prevData = $('Parse Generator').first().json;

if (prevData.status === 'generator_failed') {
  return [{
    json: {
      category: prevData.category,
      cases: [],
      stats: { generated: 0, validated: 0, corrected: 0, rejected: 0 },
      error: prevData.generatorError
    }
  }];
}

if (input.error) {
  // Reviewer failed, use generated cases as-is
  console.log(`[Dataset Generator] Reviewer failed, using raw cases for ${prevData.category}`);
  return [{
    json: {
      category: prevData.category,
      cases: prevData.generatedCases,
      stats: { generated: prevData.generatedCases.length, validated: prevData.generatedCases.length, corrected: 0, rejected: 0 },
      reviewerSkipped: true
    }
  }];
}

try {
  const content = input.choices?.[0]?.message?.content;
  const review = JSON.parse(content);

  const validatedCases = review.validated_cases || [];
  const corrections = review.corrections || [];
  const rejected = review.rejected || [];

  // Merge validated + corrected
  const finalCases = [...validatedCases, ...corrections];

  console.log(`[Dataset Generator] Category ${prevData.category}: ${validatedCases.length} validated, ${corrections.length} corrected, ${rejected.length} rejected`);

  return [{
    json: {
      category: prevData.category,
      cases: finalCases,
      stats: {
        generated: prevData.generatedCases.length,
        validated: validatedCases.length,
        corrected: corrections.length,
        rejected: rejected.length
      },
      rejectedDetails: rejected.length > 0 ? rejected : null
    }
  }];
} catch (e) {
  // Parse error, use generated cases
  console.log(`[Dataset Generator] Reviewer parse error for ${prevData.category}: ${e.message}`);
  return [{
    json: {
      category: prevData.category,
      cases: prevData.generatedCases,
      stats: { generated: prevData.generatedCases.length, validated: prevData.generatedCases.length, corrected: 0, rejected: 0 },
      reviewerParseError: e.message
    }
  }];
}

const result = $input.first().json;

// Store in static data for aggregation
const staticData = $getWorkflowStaticData('global');
if (!staticData.categoryResults) {
  staticData.categoryResults = [];
}
staticData.categoryResults.push(result);

return [{ json: result }];

const config = $('Validate Input').first().json.config;
const staticData = $getWorkflowStaticData('global');
const categoryResults = staticData.categoryResults || [];

// Aggregate all cases
let allCases = [];
let totalStats = { generated: 0, validated: 0, corrected: 0, rejected: 0 };
const byCategory = {};
const errors = [];

let globalId = 1;
for (const result of categoryResults) {
  byCategory[result.category] = result.cases.length;
  totalStats.generated += result.stats.generated;
  totalStats.validated += result.stats.validated;
  totalStats.corrected += result.stats.corrected;
  totalStats.rejected += result.stats.rejected;

  if (result.error) {
    errors.push({ category: result.category, error: result.error });
  }

  for (const c of result.cases) {
    allCases.push({
      id: globalId++,
      categorie: c.categorie || result.category,
      demande_utilisateur: c.demande_utilisateur || '',
      next_action_attendu: c.next_action_attendu || '',
      outils_obligatoires: c.outils_obligatoires || '',
      entites_a_resoudre: c.entites_a_resoudre || '',
      missing_blocking: c.missing_blocking || '',
      notes_testeur: c.notes_testeur || ''
    });
  }
}

// Generate CSV
const headers = 'id;categorie;demande_utilisateur;next_action_attendu;outils_obligatoires;entites_a_resoudre;missing_blocking;notes_testeur;result_next_action;result_tools;result_thinking_decision;result_status;langfuse_trace_url;execution_date';

function escapeCsv(val) {
  if (val === null || val === undefined) return '';
  const str = String(val);
  if (str.includes(';') || str.includes('"') || str.includes('\n')) {
    return '"' + str.replace(/"/g, '""') + '"';
  }
  return str;
}

const rows = allCases.map(c => [
  c.id,
  escapeCsv(c.categorie),
  escapeCsv(c.demande_utilisateur),
  escapeCsv(c.next_action_attendu),
  escapeCsv(c.outils_obligatoires),
  escapeCsv(c.entites_a_resoudre),
  escapeCsv(c.missing_blocking),
  escapeCsv(c.notes_testeur),
  '', '', '', '', '', ''
].join(';'));

const csvContent = headers + '\n' + rows.join('\n');

// Generate filename
const timestamp = new Date().toISOString().replace(/[-:]/g, '').replace('T', '_').substring(0, 15);
const domainSlug = config.domain.replace(/[^a-zA-Z0-9]/g, '_').toLowerCase();
const filename = `rfc037_test_dataset_${domainSlug}_${timestamp}.csv`;
const filepath = `/tmp/datasets/${filename}`;

// Clear static data
staticData.categoryResults = [];

return [{
  json: {
    success: true,
    dataset: {
      filename,
      filepath,
      domain: config.domain,
      total_cases: allCases.length,
      by_category: byCategory,
      validation: {
        generated: totalStats.generated,
        validated: totalStats.validated,
        corrected: totalStats.corrected,
        rejected: totalStats.rejected
      },
      errors: errors.length > 0 ? errors : null
    },
    csvContent,
    config
  }
}];
